      "overview": "Обяснява понятието „научна парадигма“ според Томас Кун и разграничава периодите на нормална наука, криза и научна революция (смяна на парадигмата). Илюстрира с исторически примери как смяната на научните парадигми променя картината на света. В труда си „Структурата на научните революции“ Томас Кун въвежда понятието „научна парадигма“ – общоприета от научната общност система от теоретични предпоставки, закони, методи и образци за решаване на задачи. Развитието на науката не е просто линейно натрупване на факти, а преминава през периоди на „нормална наука“ (решаване на главоблъсканици вътре в парадигмата), натрупване на аномалии, криза и „научна революция“, при която старата парадигма се заменя с нова, несъизмерима с нея.",
