      "Кои са ключовите понятия и идеи в темата „Автомат и изкуствен интелект“? — автомат, техника и изкуствен интелект (ИИ), тест на Тюринг и проблемът за машинното съзнание. Съвременното развитие на компютърните науки и изкуствения интелект (ИИ) възражда философския спор дали машината може да мисли и да притежава съзнание. Алън Тюринг предлага поведенчески критерий (Тест на Тюринг / „имитационна игра“), според който машина, чиито отговори в диалог не могат да бъдат различени от човешките, проявява интелигентност. В отговор Джон Сърл формулира мисловния експеримент „Китайската стая“, доказвайки, че компютърът извършва само формална манипулация със символи (синтаксис), без реално разбиране на смисъла (семантика) и без съзнателна интенционалност.",
