    "originalNoteExcerpt": "Ключови понятия: научен факт, закон, закономерност и причинно обяснение, технонаука и устойчиво развитие. Описва научното обяснение на природните явления чрез емпирични факти, причинно-следствени връзки и общи природни закони. Оценява критично превръщането на съвременната наука в технонаука и необходимостта от устойчиво развитие и екологична отговорност.",
