      "overview": "Описва научното обяснение на природните явления чрез емпирични факти, причинно-следствени връзки и общи природни закони. Оценява критично превръщането на съвременната наука в технонаука и необходимостта от устойчиво развитие и екологична отговорност. Научното обяснение в науките за природата установява обективни емпирични факти и ги подвежда под общи причинно-следствени закони и математически формулирани закономерности, което позволява точно предвиждане и техническо приложение. В съвременната епоха науката и техниката се сливат в мощна технонаука, чието безконтролно въздействие върху биосферата и човешкото здраве налага философско и етично осмисляне чрез концепцията за устойчиво развитие.",
