    "title": "История и исторически етапи",
    "originalNoteExcerpt": "Ключови понятия: философия на историята, прогрес и историческа еволюция, затворено и отворено общество (Карл Попер), студени и топли общества (Клод Леви-Строс). Сравнява класическите философски концепции за смисъла, посоката и периодизацията на историята (Хегел – прогрес в съзнанието за свобода; Маркс – смяна на обществено-икономическите формации; Огюст Конт – закон за трите стадия; Освалд Шпенглер – цикъл на локалните култури и цивилизации). Разграничава статични и динамични общества и култури („затворено“ и „отворено“ общество според Карл Попер; „студени“ и „топли“ общества според Клод Леви-Строс).",
