      "Кои са ключовите понятия и идеи в темата „Личност и промяна“? — vita contemplativa (съзерцателен живот) и vita activa (деен живот – Хана Арент), човешка ситуация, конформизъм, активизъм и личностна промяна. В книгата си „Човешката ситуация“ Хана Арент анализира двете фундаментални нагласи на човека към света: съзерцателния живот (vita contemplativa – философското съзерцание на вечната истина) и дейния живот (vita activa), който включва три основни дейности: труд (поддържане на биологичния живот), произвеждане (създаване на траен предметен свят на културата) и действие (свободното политическо общуване и инициатива между равни граждани в публичното пространство). Личностното развитие изисква преодоляване на пасивния конформизъм чрез съзнателен активизъм, управление на собственото време и отговорно проектиране на житейската промяна.",
