      "Кои са ключовите понятия и идеи в темата „Свобода и ценности“? — факт и ценност; цена и достойнство, ценностна система и йерархия на ценностите (Макс Шелер), нихилизъм и преоценка на ценностите (Ницше), екзистенциален избор и отговорност (Сартр). Свободата е фундаменталното условие за съществуването на моралните ценности. В аксиологията се прави строго разграничение между факт (описание на онова, което е) и ценност (оценка за значимост и норма за онова, което трябва да бъде), както и между пазарна цена (външен разменен еквивалент на вещите) и вътрешно достойнство (безусловна ценност на личността според Кант). Макс Шелер подрежда ценностите в обективна йерархия (сетивни/хедонистични, витални, духовни – естетически, правови, познавателни и висши религиозни ценности на святото). Фридрих Ницше диагностицира европейския нихилизъм (обезценяването на висшите ценности) и призовава към „преоценка на всички ценности“, а екзистенциалистът Жан-Пол Сартр защитава радикалната свобода („съществуването предхожда същността“ – човекът е „осъден да бъде свободен“ и чрез своя избор сам твори своите ценности и носи пълна отговорност).",
