    "originalNoteExcerpt": "Ключови понятия: инструментално отношение към природата като ресурс (Бейкън, Декарт), потребителство и екологична криза. Анализира новоевропейския проект за господство на човека над природата чрез науката и техниката („Знанието е сила“ – Франсис Бейкън; Декарт) и превръщането на природата в суровинен ресурс и средство. Оценява критически последиците от индустриализацията, технокрацията и свръхпотребителството (Мартин Хайдегер, Алвин Тофлър).",
