      "Кои са ключовите понятия и идеи в темата „Равенство“? — гражданско и правно равенство, социално неравенство и равенство на възможностите. Равенството като социална и политическа ценност не означава биологично уеднаквяване на хората, а тяхната равноценност като морални личности (равенство в достойнството) и граждани. Жан-Жак Русо разграничава естественото (физическо) неравенство от конвенционалното (обществено-политическо и имуществено) неравенство, възникнало с частната собственост. В модерната демокрация основни са гражданско-правното равенство (изономия – равенство на всички пред закона) и равенството на възможностите (равен старт за образование и развитие), докато Карл Маркс поставя акцента върху преодоляването на класовото и икономическото неравенство.",
