      "Кои са ключовите понятия и идеи в темата „Аргументация и език“? — рационалност, аргументация и структура на аргумента (теза и предпоставки), понятие (термин) – съдържание и обем, дефиниция (определение) и правила за дефиниране. Аргументацията е рационална речева и мисловна дейност за обосноваване на твърдение пред аудитория. Всеки аргумент има логическа структура от три елемента: теза (твърдението, което се доказва), аргументи / предпоставки (истинни съждения, приведени в подкрепа на тезата) и демонстрация (логическата връзка от предпоставките към тезата). Понятията (термините) се характеризират със съдържание (съвкупността от съществени признаци) и обем (множеството от предмети, за които се отнася понятието), свързани със закона за обратното отношение: колкото по-богато е съдържанието, толкова по-тесен е обемът. Класическата дефиниция се изгражда чрез най-близкия род и видовата отлика (напр. „Човекът е разумно живо същество“) и трябва да бъде съразмерна, ясна и без логически кръг.",
