        "Философски и психологически идеи: Критичното и креативното (творческото) мислене изисква първо да се разпознаят и преодолеят когнитивните препятствия: некритичното мнение, предразсъдъците, суеверията и описаните от Франсис Бейкън четири вида „идоли на ума“ – идоли на рода (общи несъвършенства на човешката природа), на пещерата (лични пристрастия и ограничен опит), на площада/пазара (неточности и шаблони на езика) и на театъра (сляпо доверие в догматични системи и авторитети). За преодоляването им философията използва методичното съмнение (Декарт), критиката на разума (Кант), диалектиката (Хегел), рефлексивното проблемно мислене (Джон Дюи), лингвистичния анализ (Витгенщайн) и евристичните техники като мисловния експеримент и мозъчната атака.",
        "Очаквани резултати по МОН: Разпознава препятствията пред критичното и творческото мислене: предразсъдъци, суеверия, догматизъм и „идоли на ума“ (Франсис Бейкън). Прилага философски методи и евристични техники за преодоляване на когнитивните бариери и генериране на нови идеи: методично съмнение (Декарт), критика на разума (Кант), диалектика (Хегел), рефлексивно мислене (Джон Дюи), лингвистичен анализ (Витгенщайн) и мисловен експеримент.",
