    "originalNoteExcerpt": "Ключови понятия: личностна идентичност и групова (социална) идентичност, символен интеракционизъм (Дж. Х. Мийд) и социален характер (Ерих Фром), етническа принадлежност и социоикономически статус. Обяснява взаимодействието между личностната идентичност (уникалните характеристики на Аза) и социалната/груповата идентичност (принадлежност към социални, етнически, културни и професионални групи) в теориите на Джордж Хърбърт Мийд (символен интеракционизъм – „I“ и „Me“) и Ерих Фром. Анализира влиянието на социоикономическия статус и груповата принадлежност върху самооценката и поведението на личността.",
