    "originalNoteExcerpt": "Ключови понятия: междуличностен и групов конфликт; агресия, стратегии за разрешаване на конфликти (Томас – Килман): избягване, налагане, приспособяване, компромис и сътрудничество. Анализира структурата, причините и динамиката на междуличностните и груповите конфликти и разграничава деструктивната агресия от конструктивното решаване на проблема. Прилага модела на Томас – Килман за петте стратегии за поведение в конфликт според баланса между собствен интерес и интерес на другия: съперничество (налагане), избягване, приспособяване (отстъпване), компромис и сътрудничество (печеля–печелиш).",
