      "Кои са ключовите понятия и идеи в темата „Политическо участие“? — гражданско общество, правова държава и гражданско участие, корупция и конфликт на интереси. Демократичната правова държава се основава върху върховенството на закона и разделението на властите на законодателна, изпълнителна и съдебна (Джон Лок, Шарл Луи дьо Монтескьо), които взаимно се контролират и възпират. Жизнеността на демокрацията зависи от развитото гражданско общество – сферата на свободните сдружения, медиите и гражданските инициативи, независима от държавния апарат. Политическото участие включва гласуване на избори, референдуми, петиции, мирни протести и доброволчество. Основни деформации и заплахи за публичната власт са корупцията (злоупотреба с публична власт за лична облага) и конфликтът на интереси (когато длъжностно лице има частен интерес, който може да повлияе върху безпристрастното изпълнение на служебните му задължения).",
