      "overview": "Анализира глобализацията като многоизмерен икономически, политически, информационен и културен процес и метафората за света като „глобално село“ (Маршал Маклуън). Оценява трансформацията на суверенитета на националната държава и взаимовръзката между глобални и локални процеси (глокализация), кризи и конфликти. Глобализацията е обективен исторически процес на нарастваща икономическа, технологична, информационна, политическа и културна взаимосвързаност на света. Канадският философ Маршал Маклуън въвежда метафората „глобално село“, за да опише как електронните медии и комуникации свиват пространството и времето и превръщат планетата в единна общност, преживяваща събитията в реално време. Глобализацията трансформира класическия суверенитет на националната държава и поражда диалектиката между глобално и локално (глокализация – адаптиране на глобалните процеси към местните културни традиции).",
