      "Кои са ключовите понятия и идеи в темата „Глобализацията като процес“? — глобализация, глокализация и „глобално село“ (Маклуън), национална държава, глобални и локални кризи. Глобализацията е обективен исторически процес на нарастваща икономическа, технологична, информационна, политическа и културна взаимосвързаност на света. Канадският философ Маршал Маклуън въвежда метафората „глобално село“, за да опише как електронните медии и комуникации свиват пространството и времето и превръщат планетата в единна общност, преживяваща събитията в реално време. Глобализацията трансформира класическия суверенитет на националната държава и поражда диалектиката между глобално и локално (глокализация – адаптиране на глобалните процеси към местните културни традиции).",
