      "overview": "Съпоставя политическите и културните модели за взаимодействие между различни общности: асимилация, сегрегация, интеграция, мултикултурализъм и интеркултурализъм. Анализира отношението между доминираща култура, субкултури и културна идентичност в условията на плурализъм и толерантност. В условията на културно многообразие съществуват различни политически модели за регулиране на отношенията между доминиращата култура, малцинствата и субкултурите: 1) Сегрегация (изолиране и разделяне на общностите); 2) Асимилация (принудително или пълно претопяване на малцинствената култура в доминиращата); 3) Мултикултурализъм (признаване и съвместно съществуване на различни културни общности със запазване на тяхната групова идентичност); 4) Интеркултурализъм (активен диалог, взаимно опознаване и взаимодействие между културите върху основата на общи конституционни и демократични ценности и права на човека).",
