    "title": "Психологически теории за личността",
    "originalNoteExcerpt": "Ключови понятия: психоанализа (Фройд – То, Аз, Свръх-Аз и несъзнавано), темперамент и теории за личностните черти, хуманистични и социо-когнитивни теории за личността. Сравнява основните психологически парадигми за личността: психоанализа (Зигмунд Фройд – несъзнавано, То/Id, Аз/Ego, Свръх-Аз/Superego и защитни механизми; Карл Густав Юнг), теории за личностните черти и темперамента (Олпорт, Айзенк, „Голямата петорка“), социо-когнитивни теории (Алберт Бандура – самоефикасност и учене чрез наблюдение) и хуманистична психология (Ейбрахам Маслоу, Карл Роджърс). Съпоставя теориите за личността по осите: свобода срещу детерминизъм, наследственост срещу среда, устойчивост срещу промяна.",
