      "Кои са ключовите понятия и идеи в темата „Сексуалност и културни проявления на пола“? — биологичен пол, полова идентичност и социални полови роли, сексуална ориентация и превенция на сексуалното насилие. Психологическият и социалният анализ на човешката сексуалност разграничава понятията: биологичен пол (анатомо-физиологичните и генетични характеристики), социален пол и полови роли (исторически и културно формираните очаквания за поведението на мъжете и жените в общества с матриархална, патриархална или егалитарна традиция), полова идентичност (вътрешното самоосъзнаване на личността като принадлежаща към определен пол) и сексуална ориентация. Зрялата личност се характеризира с уважение към човешкото достойнство, равнопоставеност на половете и категорична нетърпимост към всякакъв вид сексуален тормоз и насилие.",
      "Какъв е класическият пример за „Сексуалност и културни проявления на пола“? — Разделението на професиите на „изцяло мъжки“ и „изцяло женски“ в миналото не е биологичен закон, а исторически променящ се културен стереотип за половите роли."
