      "Кои са ключовите понятия и идеи в темата „Познавателни способности и интелигентност“? — познавателни процеси: възприятие, аперцепция, памет, въображение и мислене, когнитивна, емоционална, социална и множествена интелигентност (Гарднър, Голман). Познавателната (когнитивната) сфера на психиката включва процесите усещане (отразяване на отделни сетивни качества), възприятие (цялостен сетивен образ на предмета, зависим от миналия опит и нагласите на личността – аперцепция), внимание, памет (кодиране, съхраняване и възпроизвеждане в краткосрочна и дългосрочна памет), въображение и мислене (обобщено и опосредствано познание на съществените връзки). Наред с класическото измерване на общата когнитивна интелигентност (IQ), Хауърд Гарднър създава теорията за множествената интелигентност (лингвистична, логико-математическа, пространствена, музикална, телесно-кинестетична, междуличностна, вътрешноличностна и натуралистична), а Даниел Голман обосновава ключовата роля на емоционалната интелигентност (EQ – самосъзнание, самоконтрол, мотивация, емпатия и социални умения).",
      "Какъв е класическият пример за „Познавателни способности и интелигентност“? — Явлението аперцепция обяснява защо ботаник, художник и дървосекач, гледайки една и съща гора, възприемат и забелязват различни детайли в нея в зависимост от своя професионален опит и интереси."
