    "originalNoteExcerpt": "Ключови понятия: жизнен цикъл (детство, юношество, зряла възраст, старост) и криза на идентичността (Ерик Ериксон), стадии на когнитивно развитие (Жан Пиаже), предконвенционално, конвенционално и постконвенционално морално развитие (Лорънс Колбърг). Сравнява класическите периодизации на развитието на личността през жизнения цикъл (пренатално развитие, бебешка възраст, детство, юношество, зряла възраст, старост): когнитивно развитие в 4 стадия при Жан Пиаже, морално развитие в 3 нива (предконвенционално, конвенционално и постконвенционално) при Лорънс Колбърг и 8-те психосоциални стадия и кризи на идентичността при Ерик Ериксон. Оценява ролята на семейството, връстниците, езика и общуването за формирането на идентичността в юношеството.",
