    "title": "Екзистенциални ситуации и кризи – предизвикателство и справяне",
    "originalNoteExcerpt": "Ключови понятия: гранична (екзистенциална) ситуация и криза, страдание, страх от смъртта, смисъл и безсмислие, логотерапия и воля за смисъл (Виктор Франкл); отговорност и справяне. Обяснява понятието „гранична (екзистенциална) ситуация“ (страдание, вина, борба, случайност, страх от смъртта – Карл Ясперс) и проблема за абсурда и бунта при Албер Камю. Прилага идеите на логотерапията на Виктор Франкл за волята за смисъл, отговорността и превръщането на кризата и страданието във възможност за личностно израстване и себеосъществяване.",
